"""Random strings for the vowel counter: one line of ASCII.

Nothing here goes outside plain ASCII. The problem warns about passing a
negative `char` to `tolower`, but a generated case that only fails on some
machines would be a worse test than the warning is a hint.
"""

VOWELS = "aeiou"
CONSONANTS = "bcdfghjklmnpqrstvwxz"


def generate(rng, count):
    builders = (_word, _mixed_case, _no_vowels, _sentence)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, text, description=""):
    return {"name": name, "stdin": text + "\n", "description": description}


def _letters(rng, length, alphabet=VOWELS + CONSONANTS):
    return "".join(rng.choice(alphabet) for _ in range(length))


def _word(rng, index):
    return _case("a word #%d" % index, _letters(rng, rng.randint(6, 14)))


def _mixed_case(rng, index):
    text = _letters(rng, rng.randint(8, 14))
    shouted = "".join(c.upper() if rng.random() < 0.5 else c for c in text)
    return _case("mixed case #%d" % index, shouted,
                 "Upper and lower case both count.")


def _no_vowels(rng, index):
    return _case("no vowels #%d" % index,
                 _letters(rng, rng.randint(5, 10), CONSONANTS + "y"),
                 "Consonants only. 'y' is not a vowel here.")


def _sentence(rng, index):
    words = [_letters(rng, rng.randint(2, 7)) for _ in range(rng.randint(3, 5))]
    return _case("a sentence #%d" % index, " ".join(words) + ".",
                 "Spaces and punctuation are not vowels either.")
